        ctx.lines(args!["^3355FFYou run away", "from Bai Long as", "fast as you can!^000000"])?;
        ctx.close_window()?;
        ctx.call(Function::Warp, vec![Val::from("louyang"), Val::from(218), Val::from(246)])?;
        return Err(Stop::End);
